const CONTENT = [
  {id:'breath_calm_1m',kind:'breathing',goal:'calm',title:'한숨 돌리기',minutes:1,icon:'◌',desc:'짧게 호흡의 리듬을 되찾아요.'},
  {id:'breath_calm_3m',kind:'breathing',goal:'calm',title:'3분 마음 호흡',minutes:3,icon:'◎',desc:'4초 들숨, 6초 날숨을 따라가요.'},
  {id:'breath_calm_5m',kind:'breathing',goal:'calm',title:'천천히 가라앉기',minutes:5,icon:'◍',desc:'잔잔한 파동과 함께 긴장을 놓아요.'},
  {id:'focus_5m',kind:'meditation',goal:'focus',title:'흐트러진 집중 모으기',minutes:5,icon:'✦',desc:'지금 할 한 가지에 시선을 모아요.'},
  {id:'rest_3m',kind:'meditation',goal:'rest',title:'조용한 쉼표',minutes:3,icon:'❋',desc:'잠시 멈추고 몸의 감각을 살펴요.'},
  {id:'sleep_rain_30m',kind:'sound',goal:'sleep',title:'비와 브라운 노이즈',minutes:30,icon:'☂',desc:'생각이 잦아드는 부드러운 수면 믹스.'},
  {id:'sleep_ocean_30m',kind:'sound',goal:'sleep',title:'밤바다의 호흡',minutes:30,icon:'≈',desc:'느린 파도에 맞춰 잠을 준비해요.'},
  {id:'calm_body_10m',kind:'meditation',goal:'calm',title:'몸의 긴장 내려놓기',minutes:10,icon:'◇',desc:'머리부터 발끝까지 차분히 이완해요.'}
];
const SOUNDS=[{id:'rain',name:'부드러운 비',icon:'☂',freq:420,type:'rain'},{id:'ocean',name:'느린 파도',icon:'≈',freq:170,type:'wave'},{id:'forest',name:'밤의 숲',icon:'♧',freq:720,type:'forest'},{id:'fire',name:'모닥불',icon:'♨',freq:260,type:'fire'},{id:'white',name:'화이트 노이즈',icon:'◫',freq:500,type:'white'},{id:'brown',name:'브라운 노이즈',icon:'◼',freq:90,type:'brown'}];
const DEFAULT={checkin:null,sessions:[],favorites:[],settings:{reducedMotion:false,haptics:false},mix:{rain:55,brown:38},sleepMinutes:30};
let state=load(); let ticker=null; let activeSession=null; let audio=null; let sleepNodes=[];
function load(){try{return {...structuredClone(DEFAULT),...JSON.parse(localStorage.getItem('moa-state')||'{}')}}catch{return structuredClone(DEFAULT)}}
function save(){try{localStorage.setItem('moa-state',JSON.stringify(state))}catch{toast('저장 공간이 부족해 변경 내용을 저장하지 못했어요.')}}
function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),2200)}
function header(){return `<header class="topbar"><div class="brand"><span class="brand-mark">M</span>Moa</div><button class="icon-btn" data-checkin aria-label="현재 상태 확인">♡</button></header>`}
function route(){const h=location.hash||'#/';if(h.startsWith('#/session/'))return ['session',h.split('/')[2]];return [h.slice(2)||'home']}
function nav(active){document.querySelectorAll('.bottom-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===active));document.querySelector('.bottom-nav').hidden=active==='session'||active==='check-in'}
function recommendation(){const goal=state.checkin?.goal||'calm', mins=state.checkin?.minutes||3;return CONTENT.map(c=>{let score=c.goal===goal?40:0;score+=c.minutes===mins?20:Math.abs(c.minutes-mins)<=2?10:0;if(state.favorites.includes(c.id))score+=8;const own=state.sessions.filter(s=>s.contentId===c.id).slice(-3);if(own.some(s=>s.helpful===true))score+=15;if(own.filter(s=>s.status==='stopped').length>=2)score-=20;if(own.filter(s=>s.helpful===false).length>=2)score-=15;return {c,score}}).sort((a,b)=>b.score-a.score||a.c.id.localeCompare(b.c.id))[0].c}
function reason(c){if(state.favorites.includes(c.id))return '즐겨찾기에 담아둔 세션이에요';if(state.sessions.some(s=>s.contentId===c.id&&s.helpful))return '지난번에 도움 됐어요';if(state.checkin)return `${{calm:'긴장 완화',sleep:'잠들기',focus:'집중',rest:'휴식'}[state.checkin.goal]}를 선택해 추천해요`;return '처음 시작하기 좋은 세션이에요'}
function home(){const r=recommendation();return `${header()}<section class="hero"><span class="eyebrow">오늘의 마음 날씨</span><h1>${state.checkin?`지금의 나에게,<br>부드러운 ${state.checkin.minutes}분`:'지금, 어떤 도움이<br>필요한가요?'}</h1><p>상태를 알려주면 지금 시작하기 좋은 세션을 골라드려요. 모든 기록은 이 기기에만 남습니다.</p></section><section class="needs" aria-label="지금 필요한 것"><a class="nav-card" href="#/check-in"><span class="need-icon">◌</span><b>마음 진정</b><small>호흡으로 천천히</small></a><a class="nav-card" href="#/sleep"><span class="need-icon">☾</span><b>잠들기</b><small>소리와 함께 깊게</small></a><a class="nav-card" href="#/check-in" data-goal="focus"><span class="need-icon">✦</span><b>집중하기</b><small>흐트러진 시선 모으기</small></a><a class="nav-card" href="#/check-in" data-goal="rest"><span class="need-icon">❋</span><b>쉬어가기</b><small>잠깐의 회복</small></a></section><section class="section"><div class="section-head"><h2>오늘의 추천</h2><span class="tag">${esc(reason(r))}</span></div><article class="feature"><span class="eyebrow">FOR YOU · ${r.minutes} MIN</span><h2>${esc(r.title)}</h2><p>${esc(r.desc)}</p><div class="feature-actions"><a class="btn" href="#/session/${r.id}">▶ 시작하기</a><button class="btn secondary" data-fav="${r.id}">${state.favorites.includes(r.id)?'♥ 저장됨':'♡ 저장'}</button></div></article></section><section class="section"><div class="section-head"><h2>Quick Calm</h2><a class="text-link" href="#/explore">모두 보기</a></div><div class="quick-row">${[1,3,5].map(m=>`<button class="quick-card" data-start="breath_calm_${m}m"><span class="tag">호흡</span><div class="duration">${m}분</div><small>${m===1?'급한 마음을 잠깐 멈춰요':m===3?'4초 들이쉬고 6초 내쉬어요':'조금 더 깊게 이완해요'}</small></button>`).join('')}</div></section>${recentBlock()}`}
function recentBlock(){const last=state.sessions.at(-1);if(!last)return '';const c=CONTENT.find(x=>x.id===last.contentId);return `<section class="section"><div class="section-head"><h2>최근 들은 세션</h2></div><div class="session-card"><span class="session-art">${c?.icon||'◌'}</span><div><h3>${esc(c?.title||'이용할 수 없는 콘텐츠')}</h3><span class="meta">${last.status==='completed'?'완료':'중단'} · ${Math.round(last.playedSeconds/60)}분</span></div><a class="icon-btn" href="#/session/${c?.id||'breath_calm_3m'}" aria-label="다시 재생">▶</a></div></section>`}
function checkin(){const c=state.checkin||{mood:3,goal:'calm',minutes:3};return `${header()}<section class="page-head"><span class="eyebrow">CHECK-IN</span><h1 class="page-title">지금의 나를 알려주세요</h1><p>정답은 없어요. 가장 가까운 것을 골라주세요.</p></section><form id="checkin-form" class="panel"><div class="question"><h2>지금 기분은 어떤가요?</h2><div class="mood-row">${['😣','😕','😐','🙂','😌'].map((x,i)=>`<button type="button" class="mood-btn ${c.mood===i+1?'active':''}" data-mood="${i+1}" aria-label="기분 ${i+1}점">${x}</button>`).join('')}</div></div><div class="question"><h2>무엇이 필요하세요?</h2><div class="chips">${[['calm','마음 진정'],['sleep','잠들기'],['focus','집중'],['rest','휴식']].map(([v,l])=>`<button type="button" class="chip ${c.goal===v?'active':''}" data-choice="goal" data-value="${v}">${l}</button>`).join('')}</div></div><div class="question"><h2>얼마나 시간을 낼 수 있나요?</h2><div class="chips">${[1,3,5,10,20,30].map(v=>`<button type="button" class="chip ${c.minutes===v?'active':''}" data-choice="minutes" data-value="${v}">${v}분</button>`).join('')}</div></div><div class="form-actions"><a href="#/" class="btn secondary">건너뛰기</a><button class="btn mint" type="submit">추천 보기</button></div></form>`}
function sessionCard(c){return `<article class="session-card"><span class="session-art">${c.icon}</span><a href="#/session/${c.id}" style="color:inherit;text-decoration:none"><h3>${esc(c.title)}</h3><span class="meta">${labelKind(c.kind)} · ${c.minutes}분</span></a><button class="fav ${state.favorites.includes(c.id)?'on':''}" data-fav="${c.id}" aria-label="즐겨찾기">${state.favorites.includes(c.id)?'♥':'♡'}</button></article>`}
function labelKind(k){return {breathing:'호흡',meditation:'명상',sound:'사운드'}[k]}
function explore(){return `${header()}<section class="page-head"><span class="eyebrow">EXPLORE</span><h1 class="page-title">나에게 맞는 세션 찾기</h1><p>짧은 호흡부터 긴 수면 사운드까지 살펴보세요.</p></section><input class="search" id="search" type="search" placeholder="세션 이름 검색" aria-label="세션 검색"><div class="chips" id="filters">${[['all','전체'],['breathing','호흡'],['meditation','명상'],['sound','사운드'],['favorite','저장됨']].map(([v,l],i)=>`<button class="chip ${i===0?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div><section class="section"><div class="card-grid" id="results">${CONTENT.map(sessionCard).join('')}</div></section>`}
function sleep(){const on=Object.keys(state.mix);return `${header()}<section class="page-head"><span class="eyebrow">SLEEP MODE</span><h1 class="page-title">오늘 밤, 생각을 내려놓아요</h1><p>좋아하는 소리를 최대 4개까지 섞어보세요.</p></section><div class="sleep-layout"><section class="sleep-hero"><div class="sleep-orb" aria-hidden="true"></div><span class="eyebrow">NIGHT MIX</span><h2>나만의 수면 풍경</h2><p class="meta">선택한 소리가 자연스럽게 겹쳐져요.</p><div class="chips">${[15,30,60,0].map(v=>`<button class="chip ${state.sleepMinutes===v?'active':''}" data-sleep-time="${v}">${v?`${v}분`:'직접 종료'}</button>`).join('')}</div><p class="notice">모바일 브라우저의 절전 정책에 따라 화면이 잠긴 동안 재생이 중단될 수 있어요.</p></section><section class="panel"><div class="section-head"><h2>사운드 믹서</h2><span class="meta"><b id="sound-count">${on.length}</b>/4 선택</span></div><div class="sound-list">${SOUNDS.map(s=>`<div class="sound-row"><button class="sound-toggle ${state.mix[s.id]!=null?'on':''}" data-sound="${s.id}" aria-label="${s.name} 켜기">${s.icon}</button><div class="sound-control"><label for="vol-${s.id}">${s.name}</label><output id="out-${s.id}">${state.mix[s.id]??40}%</output><input id="vol-${s.id}" type="range" min="0" max="100" value="${state.mix[s.id]??40}" data-volume="${s.id}" ${state.mix[s.id]==null?'disabled':''}></div></div>`).join('')}</div><div class="sticky-action"><button class="btn mint" id="start-sleep" ${!on.length?'disabled':''}>▶ 수면 믹스 시작</button></div></section></div>`}
function insights(){const sessions=state.sessions.filter(s=>s.status==='completed');const total=Math.round(sessions.reduce((a,s)=>a+s.playedSeconds,0)/60);const days=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=d.toLocaleDateString('en-CA');const mins=Math.round(state.sessions.filter(s=>s.localDate===key&&s.status==='completed').reduce((a,s)=>a+s.playedSeconds,0)/60);return {label:['일','월','화','수','목','금','토'][d.getDay()],mins}});const activeDays=new Set(sessions.map(s=>s.localDate));let streak=0;for(let i=0;i<365;i++){const d=new Date();d.setDate(d.getDate()-i);if(activeDays.has(d.toLocaleDateString('en-CA')))streak++;else if(i>0||sessions.length)break}return `${header()}<section class="page-head"><span class="eyebrow">INSIGHTS</span><h1 class="page-title">나의 작은 변화</h1><p>잘한 날보다 다시 돌아온 날을 기억해요.</p></section><div class="stat-grid"><div class="stat"><b>${sessions.length}</b><span>완료 세션</span></div><div class="stat"><b>${total}</b><span>함께한 분</span></div><div class="stat"><b>${streak}</b><span>연속일</span></div></div><section class="panel"><div class="section-head"><h2>최근 7일</h2><span class="meta">분</span></div><div class="week">${days.map(d=>`<div class="day"><span>${d.mins||''}</span><div class="bar" style="height:${Math.max(7,Math.min(110,d.mins*5))}px"></div><span>${d.label}</span></div>`).join('')}</div></section><section class="section"><div class="section-head"><h2>최근 활동</h2></div>${state.sessions.length?`<div class="card-grid">${state.sessions.slice(-6).reverse().map(s=>{const c=CONTENT.find(x=>x.id===s.contentId);return `<div class="session-card"><span class="session-art">${c?.icon||'◌'}</span><div><h3>${esc(c?.title||'이용할 수 없음')}</h3><span class="meta">${s.localDate} · ${s.status==='completed'?'완료':'중단'}</span></div><span>${s.helpful==null?'':s.helpful?'🙂':'—'}</span></div>`}).join('')}</div>`:'<div class="empty panel">아직 기록이 없어요.<br>3분 호흡으로 가볍게 시작해볼까요?</div>'}</section>`}
function settings(){return `${header()}<section class="page-head"><span class="eyebrow">SETTINGS</span><h1 class="page-title">내 방식대로 편안하게</h1><p>기록과 재생 환경을 관리할 수 있어요.</p></section><section class="panel"><div class="setting-row"><div><b>모션 줄이기</b><small>호흡 원의 확대·축소를 멈춰요.</small></div><button class="switch ${state.settings.reducedMotion?'on':''}" data-setting="reducedMotion" role="switch" aria-checked="${state.settings.reducedMotion}"><span></span></button></div><div class="setting-row"><div><b>호흡 전환 진동</b><small>지원되는 기기에서만 작동해요.</small></div><button class="switch ${state.settings.haptics?'on':''}" data-setting="haptics" role="switch" aria-checked="${state.settings.haptics}"><span></span></button></div></section><section class="panel"><div class="setting-row"><div><b>내 데이터 내보내기</b><small>JSON 파일로 기기에 저장해요.</small></div><button class="btn secondary" id="export">내보내기</button></div><div class="setting-row"><div><b>데이터 가져오기</b><small>기존 기록을 확인 후 덮어써요.</small></div><label class="btn secondary">가져오기<input class="sr-only" id="import" type="file" accept="application/json"></label></div><div class="setting-row"><div><b>모든 데이터 삭제</b><small>이 기기의 체크인과 기록을 지워요.</small></div><button class="btn danger" id="delete">삭제</button></div></section><p class="notice">Moa는 의료 서비스가 아니며 진단이나 치료를 제공하지 않습니다. 위급한 상황에는 지역 응급 서비스에 연락해 주세요.</p>`}
function player(id){const c=CONTENT.find(x=>x.id===id)||CONTENT[1];if(!activeSession||activeSession.id!==id)initSession(c);return `<section class="player-page"><a class="icon-btn" href="${c.goal==='sleep'?'#/sleep':'#/'}" id="back" aria-label="세션 닫기">⌄</a><span class="eyebrow">${labelKind(c.kind)} · ${c.minutes} MIN</span><h1 class="page-title">${esc(c.title)}</h1><p class="meta">${esc(c.desc)}</p><div class="breath-orb" id="breath-orb"><span id="phase">준비</span></div><div class="timer" id="timer">${format(activeSession.remaining)}</div><div class="progress"><span id="progress-bar"></span></div><div class="player-controls"><button class="icon-btn" id="stop" aria-label="세션 종료">■</button><button class="play-main" id="play" aria-label="재생">▶</button><button class="icon-btn" id="restart" aria-label="처음부터">↻</button></div><p class="notice">${c.kind==='breathing'?'코로 편안히 들이쉬고, 입으로 길게 내쉬세요.':'편안한 자세로 소리에 집중해 보세요.'}</p></section>`}
function initSession(c){clearInterval(ticker);stopAudio();activeSession={id:c.id,total:c.minutes*60,remaining:c.minutes*60,played:0,playing:false,startedAt:null,phase:'준비'}}
function format(sec){const m=Math.floor(sec/60),s=Math.max(0,Math.ceil(sec%60));return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function render(){const [r,id]=route();nav(r);const app=document.querySelector('#app');const pages={home,'check-in':checkin,explore,sleep,insights,settings};app.innerHTML=r==='session'?player(id):(pages[r]||home)();bind(r);window.scrollTo({top:0,behavior:'instant'})}
function bind(r){document.querySelectorAll('[data-checkin]').forEach(x=>x.onclick=()=>location.hash='#/check-in');document.querySelectorAll('[data-fav]').forEach(x=>x.onclick=()=>toggleFav(x.dataset.fav));document.querySelectorAll('[data-start]').forEach(x=>x.onclick=()=>location.hash=`#/session/${x.dataset.start}`);document.querySelectorAll('[data-goal]').forEach(x=>x.onclick=()=>{state.checkin={mood:3,goal:x.dataset.goal,minutes:5};save()});if(r==='check-in')bindCheckin();if(r==='explore')bindExplore();if(r==='sleep')bindSleep();if(r==='session')bindPlayer();if(r==='settings')bindSettings()}
function toggleFav(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();toast(state.favorites.includes(id)?'즐겨찾기에 저장했어요.':'즐겨찾기에서 뺐어요.');render()}
function bindCheckin(){let draft={...(state.checkin||{mood:3,goal:'calm',minutes:3})};document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{draft.mood=+b.dataset.mood;document.querySelectorAll('[data-mood]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{draft[b.dataset.choice]=b.dataset.choice==='minutes'?+b.dataset.value:b.dataset.value;document.querySelectorAll(`[data-choice="${b.dataset.choice}"]`).forEach(x=>x.classList.toggle('active',x===b))});document.querySelector('#checkin-form').onsubmit=e=>{e.preventDefault();state.checkin={...draft,createdAt:new Date().toISOString()};save();toast('지금 상태에 맞춰 추천을 바꿨어요.');location.hash='#/'}}
function bindExplore(){let filter='all';const update=()=>{const q=document.querySelector('#search').value.trim().toLowerCase();const data=CONTENT.filter(c=>(filter==='all'||c.kind===filter||filter==='favorite'&&state.favorites.includes(c.id))&&(`${c.title} ${c.desc}`.toLowerCase().includes(q)));document.querySelector('#results').innerHTML=data.map(sessionCard).join('')||'<div class="empty panel">조건에 맞는 세션이 없어요.</div>';document.querySelectorAll('[data-fav]').forEach(x=>x.onclick=()=>toggleFav(x.dataset.fav))};document.querySelector('#search').oninput=update;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));update()})}
function bindSleep(){document.querySelectorAll('[data-sound]').forEach(b=>b.onclick=()=>{const id=b.dataset.sound;if(state.mix[id]!=null)delete state.mix[id];else if(Object.keys(state.mix).length<4)state.mix[id]=40;else return toast('사운드는 최대 4개까지 섞을 수 있어요.');save();render()});document.querySelectorAll('[data-volume]').forEach(i=>i.oninput=()=>{state.mix[i.dataset.volume]=+i.value;document.querySelector(`#out-${i.dataset.volume}`).textContent=`${i.value}%`;save()});document.querySelectorAll('[data-sleep-time]').forEach(b=>b.onclick=()=>{state.sleepMinutes=+b.dataset.sleepTime;save();render()});document.querySelector('#start-sleep').onclick=()=>{const id=state.sleepMinutes?'sleep_rain_30m':'sleep_ocean_30m';const c={...CONTENT.find(x=>x.id===id),minutes:state.sleepMinutes||30};CONTENT.find(x=>x.id===id).minutes=c.minutes;location.hash=`#/session/${id}`}}
function bindPlayer(){document.querySelector('#play').onclick=togglePlay;document.querySelector('#stop').onclick=()=>finish(false);document.querySelector('#restart').onclick=()=>{const c=CONTENT.find(x=>x.id===activeSession.id);initSession(c);updatePlayer()};document.querySelector('#back').onclick=e=>{if(activeSession.played>0&&!confirm('진행 중인 세션을 중단할까요?'))e.preventDefault();else if(activeSession.played>0)record(false)}}
function togglePlay(){activeSession.playing=!activeSession.playing;if(activeSession.playing){if(!activeSession.startedAt)activeSession.startedAt=new Date().toISOString();startAudio();let last=Date.now();ticker=setInterval(()=>{const now=Date.now(),delta=(now-last)/1000;last=now;if(!activeSession?.playing)return;activeSession.remaining=Math.max(0,activeSession.remaining-delta);activeSession.played+=delta;updatePlayer();if(activeSession.remaining<=0)finish(true)},250)}else{clearInterval(ticker);stopAudio()}updatePlayer()}
function updatePlayer(){if(!activeSession)return;const c=CONTENT.find(x=>x.id===activeSession.id);const timer=document.querySelector('#timer');if(!timer)return;timer.textContent=format(activeSession.remaining);document.querySelector('#progress-bar').style.width=`${(1-activeSession.remaining/activeSession.total)*100}%`;document.querySelector('#play').textContent=activeSession.playing?'Ⅱ':'▶';const phase=Math.floor(activeSession.played)%10<4?'들이쉬기':'내쉬기';const orb=document.querySelector('#breath-orb');document.querySelector('#phase').textContent=c.kind==='breathing'&&activeSession.playing?phase:activeSession.playing?'편안히 듣기':'잠시 멈춤';orb.className=`breath-orb ${c.kind==='breathing'&&activeSession.playing?(phase==='들이쉬기'?'inhale':'exhale'):''}`;if(state.settings.haptics&&phase!==activeSession.phase&&navigator.vibrate)navigator.vibrate(35);activeSession.phase=phase}
function startAudio(){try{const AudioCtx=window.AudioContext||window.webkitAudioContext;audio=audio||new AudioCtx();if(audio.state==='suspended')audio.resume();const gain=audio.createGain(),osc=audio.createOscillator(),lfo=audio.createOscillator(),lfoGain=audio.createGain();osc.type='sine';osc.frequency.value=activeSession.id.startsWith('sleep')?120:174;lfo.frequency.value=.08;lfoGain.gain.value=28;lfo.connect(lfoGain);lfoGain.connect(osc.frequency);gain.gain.value=.018;osc.connect(gain);gain.connect(audio.destination);osc.start();lfo.start();sleepNodes=[osc,lfo,gain]}catch{toast('소리를 시작하지 못했어요. 다시 눌러주세요.')}}
function stopAudio(){sleepNodes.forEach(n=>{try{n.stop?.()}catch{}try{n.disconnect?.()}catch{}});sleepNodes=[]}
function finish(done){clearInterval(ticker);stopAudio();if(!activeSession)return;record(done);const id=activeSession.id;activeSession=null;const d=document.createElement('dialog');d.innerHTML=`<h2>${done?'오늘의 세션 완료':'여기까지 기록했어요'}</h2><p>${done?'잠시 멈춘 것만으로도 충분해요. 도움이 되었나요?':'원할 때 언제든 다시 돌아오세요.'}</p>${done?'<div class="rating"><button class="btn mint" data-help="true">도움 됐어요</button><button class="btn secondary" data-help="false">잘 모르겠어요</button></div>':''}<button class="btn secondary" data-close>홈으로</button>`;document.body.append(d);d.showModal();d.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>{state.sessions.at(-1).helpful=b.dataset.help==='true';save();d.close();d.remove();location.hash='#/'});d.querySelector('[data-close]').onclick=()=>{d.close();d.remove();location.hash='#/'};if(!done)setTimeout(()=>{if(d.open){d.close();d.remove();location.hash='#/'}},1200)}
function record(done){if(!activeSession||activeSession.recorded)return;activeSession.recorded=true;const c=CONTENT.find(x=>x.id===activeSession.id);const completed=done||activeSession.played>=activeSession.total*.8;state.sessions.push({id:`session_${Date.now()}`,contentId:c.id,kind:c.kind,goal:c.goal,startedAt:activeSession.startedAt||new Date().toISOString(),endedAt:new Date().toISOString(),localDate:new Date().toLocaleDateString('en-CA'),playedSeconds:Math.round(activeSession.played),targetSeconds:activeSession.total,status:completed?'completed':'stopped',helpful:null});save()}
function bindSettings(){document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{const k=b.dataset.setting;state.settings[k]=!state.settings[k];save();render()});document.querySelector('#export').onclick=()=>{const blob=new Blob([JSON.stringify({schemaVersion:1,...state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`moa-backup-${new Date().toLocaleDateString('en-CA')}.json`;a.click();URL.revokeObjectURL(a.href)};document.querySelector('#import').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.schemaVersion!==1||!Array.isArray(data.sessions)||!Array.isArray(data.favorites))throw 0;if(confirm('현재 데이터를 가져온 파일로 덮어쓸까요?')){delete data.schemaVersion;state={...structuredClone(DEFAULT),...data};save();toast('데이터를 가져왔어요.');render()}}catch{toast('올바른 Moa 백업 파일이 아니에요.')}};document.querySelector('#delete').onclick=()=>{if(confirm('모든 기록과 설정을 삭제할까요? 이 작업은 되돌릴 수 없어요.')){localStorage.removeItem('moa-state');state=structuredClone(DEFAULT);toast('이 기기의 데이터를 모두 삭제했어요.');render()}}}
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',()=>{if(activeSession?.played)record(false)});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
